package com.aoo.bcg.common.repair;import java.time.Instant;import java.util.*;import java.util.function.Supplier;
/** Mandatory multi-plane reconciliation gate after every production repair. */
public final class PostRepairReconciliation{public enum Dimension{TOTALS,CONTENT_HASH,REFERENCES,BALANCES,BUSINESS_METRICS,UI_READ_MODEL}public record Observation(boolean matched,String expected,String actual,String detail){public Observation{if(expected==null||actual==null||detail==null)throw new IllegalArgumentException("complete observation required");}}public record Report(String operationId,Instant checkedAt,Map<Dimension,Observation>observations){public Report{observations=Map.copyOf(observations);if(!observations.keySet().equals(EnumSet.allOf(Dimension.class)))throw new IllegalArgumentException("all reconciliation dimensions required");}public boolean passed(){return observations.values().stream().allMatch(Observation::matched);}}public Report reconcile(String operationId,Map<Dimension,Supplier<Observation>>probes,Instant now){if(operationId==null||operationId.isBlank()||now==null||probes==null||!probes.keySet().equals(EnumSet.allOf(Dimension.class)))throw new IllegalArgumentException("complete reconciliation probes required");Map<Dimension,Observation>results=new EnumMap<>(Dimension.class);for(Dimension dimension:Dimension.values())results.put(dimension,Objects.requireNonNull(probes.get(dimension).get()));return new Report(operationId,now,results);}}
